// Get all keys in order
const keys = Object.keys($json);

// Find where "Date of Delivery" is
const startIndex = keys.indexOf("Date of Delivery");

if (startIndex === -1) {
  throw new Error("Date of Delivery column not found");
}

let result = [];

for (let i = startIndex + 1; i < keys.length; i++) {
  const key = keys[i];
  let value = $json[key];

  // Convert to number just in case it's string
  value = Number(value);

  if (value && value > 0) {

    const isAssorted = key.toLowerCase().includes("assorted");

    let emoji = isAssorted ? "ðŸ“¦" : "ðŸª";

    let label;
    if (isAssorted) {
      label = value === 1 ? "box" : "boxes";
    } else {
      label = value === 1 ? "pc" : "pcs";
    }

    result.push(`${emoji} ${key} - ${value} ${label}`);
  }
}

return {
  json: {
    ...$json,
    flavorsSummary: result.length
      ? result.join("\n")
      : "No items selected"
  }
};
